library(haven)
library(dplyr)
library(tidyr)
library(purrr)
library(labelled)
library(readr)

# Load all input files
wave1 <- read_delim("data/input/wave_one_lsype_family_background_2020.tab", delim = "\t", show_col_types = FALSE)
wave2 <- read_delim("data/input/wave_two_lsype_family_background_2020.tab", delim = "\t", show_col_types = FALSE)
wave4 <- read_delim("data/input/wave_four_lsype_family_background_2020.tab", delim = "\t", show_col_types = FALSE)

# Merge all files by NSID using full_join
cleaned <- full_join(wave1, wave2, by = "NSID")
cleaned <- full_join(cleaned, wave4, by = "NSID")

# Define missing value mapping function
map_missing_values <- function(x) {
  x_clean <- x
  x_clean[x_clean == -999] <- -2
  x_clean[x_clean == -99] <- -3
  x_clean[x_clean == -98] <- -2
  x_clean[x_clean == -94] <- -8
  x_clean[x_clean == -92] <- -9
  x_clean[x_clean == -91] <- -1
  x_clean[x_clean == -1 & !is.na(x_clean)] <- -8
  return(x_clean)
}

# Function to get earliest valid response across waves
get_earliest_valid <- function(v1, v2, v4) {
  result <- rep(-3, length(v1))
  for (i in seq_along(v1)) {
    if (!is.na(v1[i]) && v1[i] > 0) {
      result[i] <- v1[i]
    } else if (!is.na(v2[i]) && v2[i] > 0) {
      result[i] <- v2[i]
    } else if (!is.na(v4[i]) && v4[i] > 0) {
      result[i] <- v4[i]
    } else {
      missing_codes <- c(v1[i], v2[i], v4[i])
      missing_codes <- missing_codes[!is.na(missing_codes) & missing_codes < 0]
      if (length(missing_codes) > 0) {
        result[i] <- min(missing_codes)
      }
    }
  }
  return(result)
}

# Apply missing value mapping to source variables
w1hiqualmum <- map_missing_values(wave1$W1hiqualmum)
w1hiqualdad <- map_missing_values(wave1$W1hiqualdad)
w2hiqualmum <- map_missing_values(wave2$W2hiqualmum)
w2hiqualdad <- map_missing_values(wave2$W2hiqualdad)
w4hiqualmum <- map_missing_values(wave4$w4hiqualmum)
w4hiqualdad <- map_missing_values(wave4$w4hiqualdad)

# Create consolidated detailed variables (20-category)
educdtlma <- get_earliest_valid(w1hiqualmum, w2hiqualmum, w4hiqualmum)
educdtlpa <- get_earliest_valid(w1hiqualdad, w2hiqualdad, w4hiqualdad)

# Create 5-level NVQ categories
map_to_nvq5 <- function(x) {
  result <- rep(-3, length(x))
  for (i in seq_along(x)) {
    val <- x[i]
    if (is.na(val)) {
      result[i] <- -3
    } else if (val < 0) {
      result[i] <- val
    } else if (val == 1 || val == 2 || val == 3) {
      result[i] <- 5
    } else if (val == 4) {
      result[i] <- 4
    } else if (val == 7 || val == 9) {
      result[i] <- 3
    } else if (val == 14 || val == 15) {
      result[i] <- 2
    } else if (val == 16 || val == 17 || val == 20) {
      result[i] <- 1
    } else if (val == 5 || val == 6 || val == 8 || val == 10) {
      result[i] <- 4
    } else if (val == 11 || val == 12 || val == 13) {
      result[i] <- 3
    } else if (val == 18 || val == 19) {
      result[i] <- 1
    }
  }
  return(result)
}

# Apply NVQ mapping
educma <- map_to_nvq5(educdtlma)
educpa <- map_to_nvq5(educdtlpa)

# Create final output dataframe
output <- tibble(
  NSID = cleaned$NSID,
  educdtlma = educdtlma,
  educdtlpa = educdtlpa,
  educma = educma,
  educpa = educpa
)

# Write to CSV
write_csv(output, "data/output/cleaned_data.csv")

cat("Cleaning complete.\n")
cat("Records:", nrow(output), "\n")
cat("Columns:", paste(names(output), collapse = ", "), "\n")

